(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit62-together-examples-basic"]={"id":"unit62-together-examples-basic","unitId":"6-2","chapterIds":["6-2"],"unitType":"basic","group":"6-2단원 · 4. 공동체와 조화","name":"생활 속 새 예시 · 기본 OX","level":"기본","revision":1,"originPage":"unit62","shuffleQuestions":true,"timedMode":"question","parts":[{"name":"U62-E05 · 아파트 화단 옆 낡은 벤치","items":[{"paragraphCount":2,"readingLabel":"6문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단]\n자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다. 그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다. 이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준이는 아파트 화단 옆에 버려져 있던 낡은 벤치를 이웃 몇 분과 함께 고치고 새로 칠했다. 그러자 그 벤치에 할머니들과 학생들이 앉아 이야기를 나누기 시작했다. 늘 그냥 지나치던 곳이 동네 사람들이 만나는 자리가 되었다. 하준이는 그동안 몰랐던 이웃들을 알게 되었고, 함께 사는 동네가 소중하다는 것을 깨달았다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"낡은 벤치를 함께 고치고 칠한 것은 주변 공간을 보살피는 일에, 지나치던 벤치에서 이웃과 이야기를 나누는 것은 소통할 수 있는 지점을 발견하는 것에, 함께 사는 동네가 소중하다는 깨달음은 공동체의 중요성을 깨닫는 것에 대응한다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.” “이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.”\n6문단에서 확인할 수 있어요.","evidence":{"title":"아파트 화단 옆 낡은 벤치","statement":"하준이가 마지막에 깨달은 것은 공동체의 중요성에 해당한다.","explanation":"낡은 벤치를 함께 고치고 칠한 것은 주변 공간을 보살피는 일에, 지나치던 벤치에서 이웃과 이야기를 나누는 것은 소통할 수 있는 지점을 발견하는 것에, 함께 사는 동네가 소중하다는 깨달음은 공동체의 중요성을 깨닫는 것에 대응한다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.” “이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.”\n6문단에서 확인할 수 있어요.","valid":["G06:1","G06:3"],"sources":[{"id":"G06","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"6문단","sentences":[{"id":"G06:1","text":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.","paragraph":0,"memberIds":["G06:1"],"topic":"내 주변 공간을 보살피다 보면 동네 살림(지역 살림)에 관심이 생기고, 서로 이야기를 나눌 수 있는 곳(소통할 수 있는 지점)을 찾게 된다."},{"id":"G06:2","text":"그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.","paragraph":0,"memberIds":["G06:2"],"topic":"그동안 관심 없이 지나치던 곳에서 새로운 사람들을 만나 이야기를 나누다 보면, 내가 사는 동네를 새로 보고 분명히 알게(인식하게) 된다."},{"id":"G06:3","text":"이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.","paragraph":0,"memberIds":["G06:3"],"topic":"이런 과정을 거치며 함께 살아가는 공동체가 얼마나 중요한지도 깨닫게 될 것이다."}]}]},"examplePractice":true,"id":"U62-E05-B1","type":"ox","answer":"O","changed":"하준이가 마지막에 깨달은 것은 공동체의 중요성에 해당한다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"92488585cec5f30c50ef1ef90bd7fc92c682bf1ab84bf06795e70959ffb4c9cf"},{"paragraphCount":2,"readingLabel":"6문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 6문단]\n자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다. 그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다. 이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준이는 아파트 화단 옆에 버려져 있던 낡은 벤치를 이웃 몇 분과 함께 고치고 새로 칠했다. 그러자 그 벤치에 할머니들과 학생들이 앉아 이야기를 나누기 시작했다. 늘 그냥 지나치던 곳이 동네 사람들이 만나는 자리가 되었다. 하준이는 그동안 몰랐던 이웃들을 알게 되었고, 함께 사는 동네가 소중하다는 것을 깨달았다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"낡은 벤치를 함께 고치고 칠한 것은 주변 공간을 보살피는 일에, 지나치던 벤치에서 이웃과 이야기를 나누는 것은 소통할 수 있는 지점을 발견하는 것에, 함께 사는 동네가 소중하다는 깨달음은 공동체의 중요성을 깨닫는 것에 대응한다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.” “이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.”\n6문단에서 확인할 수 있어요.","evidence":{"title":"아파트 화단 옆 낡은 벤치","statement":"하준이가 마지막에 깨달은 것은 공동체의 중요성에 해당한다.","explanation":"낡은 벤치를 함께 고치고 칠한 것은 주변 공간을 보살피는 일에, 지나치던 벤치에서 이웃과 이야기를 나누는 것은 소통할 수 있는 지점을 발견하는 것에, 함께 사는 동네가 소중하다는 깨달음은 공동체의 중요성을 깨닫는 것에 대응한다.\n근거: “자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.” “이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.”\n6문단에서 확인할 수 있어요.","valid":["G06:1","G06:3"],"sources":[{"id":"G06","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"6문단","sentences":[{"id":"G06:1","text":"자신의 주변 공간을 보살피다 보면 지역 살림에 관심을 두게 되고, 서로 소통할 수 있는 지점을 발견하게 된다.","paragraph":0,"memberIds":["G06:1"],"topic":"내 주변 공간을 보살피다 보면 동네 살림(지역 살림)에 관심이 생기고, 서로 이야기를 나눌 수 있는 곳(소통할 수 있는 지점)을 찾게 된다."},{"id":"G06:2","text":"그동안 관심을 두지 않고 지나치던 공간에서 새로운 사람들을 만나고 소통하는 과정을 통해 자신이 살아가는 지역을 다시 발견하고 인식하게 된다.","paragraph":0,"memberIds":["G06:2"],"topic":"그동안 관심 없이 지나치던 곳에서 새로운 사람들을 만나 이야기를 나누다 보면, 내가 사는 동네를 새로 보고 분명히 알게(인식하게) 된다."},{"id":"G06:3","text":"이런 과정을 통해 함께 살아가는 공동체의 중요성 또한 깨닫게 될 것이다.","paragraph":0,"memberIds":["G06:3"],"topic":"이런 과정을 거치며 함께 살아가는 공동체가 얼마나 중요한지도 깨닫게 될 것이다."}]}]},"examplePractice":true,"id":"U62-E05-B2","type":"ox","answer":"X","changed":"하준이가 마지막에 깨달은 것은 새 벤치를 사는 일의 중요성이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":17,"end":35,"before":"새 벤치를 사는 일의 중요성이다.","after":"공동체의 중요성에 해당한다."}],"editorSourceVersion":"10490de88bd44a9c8cad930c8cd4db5bda858bc01f7a906f67d0242c2b65b3d7"}]},{"name":"U62-E06 · 오래된 정자를 살린 새 공원","items":[{"paragraphCount":2,"readingLabel":"7문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 7문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 7문단]\n새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다. 새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n지안이네 동네에 새 공원을 만들기로 했다. 처음 계획은 오래된 정자와 느티나무를 모두 없애고 새로 짓는 것이었다. 주민들은 정자와 느티나무는 고쳐서 남기고, 그 옆에 새 놀이터와 턱 없는 산책로를 만들자고 했다. 완성된 공원에서 어르신들은 정자 그늘에서 쉬고, 아이들은 새 놀이터에서 놀며, 유모차와 휠체어도 산책로를 편하게 지난다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"새 놀이터와 턱 없는 산책로를 만든 것은 새로운 환경을 만드는 것에, 정자와 느티나무를 고쳐서 남긴 것은 기존 시설을 돌보고 가꾸는 노력에 대응한다. 모두가 편한 공원은 조화를 이룰 때 탄생하는 더 좋은 도시 건축 환경, 사회적 약자를 배려하는 공간과 같다.\n근거: “새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.” “새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.”\n7문단에서 확인할 수 있어요.","evidence":{"title":"오래된 정자를 살린 새 공원","statement":"지안이네 공원은 새것과 기존의 것이 조화를 이룬 모습이다.","explanation":"새 놀이터와 턱 없는 산책로를 만든 것은 새로운 환경을 만드는 것에, 정자와 느티나무를 고쳐서 남긴 것은 기존 시설을 돌보고 가꾸는 노력에 대응한다. 모두가 편한 공원은 조화를 이룰 때 탄생하는 더 좋은 도시 건축 환경, 사회적 약자를 배려하는 공간과 같다.\n근거: “새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.” “새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.”\n7문단에서 확인할 수 있어요.","valid":["G07:1","G07:2"],"sources":[{"id":"G07","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"7문단","sentences":[{"id":"G07:1","text":"새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.","paragraph":0,"memberIds":["G07:1"],"topic":"새로운 환경을 만드는 것도 중요하지만, 이미 있는 시설을 돌보고 가꾸는 노력도 중요하다."},{"id":"G07:2","text":"새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.","paragraph":0,"memberIds":["G07:2"],"topic":"새것을 계획하는 것도 필요하지만, 이미 있는 것을 잘 돌보고 가꾸면서 둘이 잘 어울릴(조화를 이룰) 때 더 좋은 도시와 건축 환경이 생겨난다. 그리고 작은 곳에서라도 사회적 약자를 배려하는 공간이 생길 수 있다."}]}]},"examplePractice":true,"id":"U62-E06-B1","type":"ox","answer":"O","changed":"지안이네 공원은 새것과 기존의 것이 조화를 이룬 모습이다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"editorSourceVersion":"8105a967cf30028b73264e4f57b23c948ca0aa6e9c06433139d4ef9be4251f34"},{"paragraphCount":2,"readingLabel":"7문단 · 새 예시 적용","sourceLabel":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 7문단","passage":"[이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기 · 7문단]\n새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다. 새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n지안이네 동네에 새 공원을 만들기로 했다. 처음 계획은 오래된 정자와 느티나무를 모두 없애고 새로 짓는 것이었다. 주민들은 정자와 느티나무는 고쳐서 남기고, 그 옆에 새 놀이터와 턱 없는 산책로를 만들자고 했다. 완성된 공원에서 어르신들은 정자 그늘에서 쉬고, 아이들은 새 놀이터에서 놀며, 유모차와 휠체어도 산책로를 편하게 지난다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit62","skills":["비교"],"why":"새 놀이터와 턱 없는 산책로를 만든 것은 새로운 환경을 만드는 것에, 정자와 느티나무를 고쳐서 남긴 것은 기존 시설을 돌보고 가꾸는 노력에 대응한다. 모두가 편한 공원은 조화를 이룰 때 탄생하는 더 좋은 도시 건축 환경, 사회적 약자를 배려하는 공간과 같다.\n근거: “새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.” “새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.”\n7문단에서 확인할 수 있어요.","evidence":{"title":"오래된 정자를 살린 새 공원","statement":"지안이네 공원은 새것과 기존의 것이 조화를 이룬 모습이다.","explanation":"새 놀이터와 턱 없는 산책로를 만든 것은 새로운 환경을 만드는 것에, 정자와 느티나무를 고쳐서 남긴 것은 기존 시설을 돌보고 가꾸는 노력에 대응한다. 모두가 편한 공원은 조화를 이룰 때 탄생하는 더 좋은 도시 건축 환경, 사회적 약자를 배려하는 공간과 같다.\n근거: “새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.” “새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.”\n7문단에서 확인할 수 있어요.","valid":["G07:1","G07:2"],"sources":[{"id":"G07","title":"이훈길, 「함께 돌보고 가꾸어야 할 도시 공간」 읽기","label":"7문단","sentences":[{"id":"G07:1","text":"새로운 환경을 만드는 것도 중요하지만 기존에 있는 시설을 돌보고 가꾸는 노력도 중요하다.","paragraph":0,"memberIds":["G07:1"],"topic":"새로운 환경을 만드는 것도 중요하지만, 이미 있는 시설을 돌보고 가꾸는 노력도 중요하다."},{"id":"G07:2","text":"새로운 것을 계획하는 것도 필요하지만 기존의 것을 잘 돌보고 가꾸면서 조화를 이룰 때 더 좋은 도시 건축 환경이 탄생하며, 사소한 곳에서라도 사회적 약자를 배려하는 공간이 생겨날 수 있다.","paragraph":0,"memberIds":["G07:2"],"topic":"새것을 계획하는 것도 필요하지만, 이미 있는 것을 잘 돌보고 가꾸면서 둘이 잘 어울릴(조화를 이룰) 때 더 좋은 도시와 건축 환경이 생겨난다. 그리고 작은 곳에서라도 사회적 약자를 배려하는 공간이 생길 수 있다."}]}]},"examplePractice":true,"id":"U62-E06-B2","type":"ox","answer":"X","changed":"지안이네 공원은 옛것을 모두 없애야 좋아진다는 것을 보여 준다.","ask":"다음 설명이 지문과 새 예시에 맞으면 O, 다르면 X를 고르세요.","highlightEvidence":true,"requiresEvidence":false,"claimEdits":[{"start":9,"end":35,"before":"옛것을 모두 없애야 좋아진다는 것을 보여 준다.","after":"새것과 기존의 것이 조화를 이룬 모습이다."}],"editorSourceVersion":"aabf48b294782c5561f0d8b629f22e21212f028a96214b7000d62ab16e6d333d"}]}],"readingBlock":"together","readingChunk":"examples"};})(window);
